                  Changes saved
                </p>
              }
              <button hlmBtn variant="outline" type="button" (click)="vm.discardEdits()">Cancel</button>
              <button hlmBtn type="submit">Save changes</button>
            </div>
          </form>
        </section>
      </div>
    </hlm-tabs>
  } @else {
