const pw = await import(pathToFileURL(`${repo}/harness/playwright/serve-and-visit.mjs`).href);

const DIST = `${repo}/dist/angular-jig/browser`;
const routes = ['dashboard', 'roster', 'detail/silverwing', 'detail/vantablack', 'missions', 'threats', 'recruit', 'settings'];

