import { pathToFileURL } from 'node:url';

const repo = 'D:/Repos/angular-jig';
const pw = await import(pathToFileURL(`${repo}/harness/playwright/serve-and-visit.mjs`).href);

const srv = await pw.serveStatic(`${repo}/dist/angular-jig/browser`, { spaFallback: true });
const browser = await pw.launchChromium();
try {
  const { page, context } = await pw.visitBreakpoint(browser, `${srv.origin}/dashboard`, 1280);
  const info = await page.evaluate(() => {
    const a = document.querySelector('a.ring-sidebar-ring');
    const cs = getComputedStyle(a);
    const r = a.getBoundingClientRect();
    const kids = [...a.querySelectorAll('*')].map((k) => {
      const kr = k.getBoundingClientRect();
      return { tag: k.tagName, cls: (k.getAttribute('class') || '').slice(0, 60), left: Math.round(kr.left), right: Math.round(kr.right), w: Math.round(kr.width), sw: k.scrollWidth, cw: k.clientWidth };
    });
    return { overflowX: cs.overflowX, left: Math.round(r.left), right: Math.round(r.right), w: Math.round(r.width), sw: a.scrollWidth, cw: a.clientWidth, kids };
  });
  console.log(JSON.stringify(info, null, 1));
  await context.close();
} finally {
  await browser.close();
  await srv.close();
}

