import { pathToFileURL } from 'node:url';

const repo = 'D:/Repos/angular-jig';
const pw = await import(pathToFileURL(`${repo}/harness/playwright/serve-and-visit.mjs`).href);

const srv = await pw.serveStatic(`${repo}/dist/angular-jig/browser`, { spaFallback: true });
const browser = await pw.launchChromium();
const problems = [];
const check = (label, ok, extra = '') => {
  console.log(`${ok ? 'PASS' : 'FAIL'} ${label}${extra ? ' :: ' + extra : ''}`);
  if (!ok) problems.push(label);
};

try {
  const { page, context } = await pw.visitBreakpoint(browser, `${srv.origin}/dashboard`, 1280);
  page.on('pageerror', (e) => problems.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') problems.push('console: ' + m.text()); });

  const rail = (name) => page.locator('nav[aria-label="Primary"] a', { hasText: name });
  const body = () => page.locator('body').innerText();

  // 1. Edit on the detail screen is reflected on the dashboard and the roster.
  await rail('Roster').click();
  await page.getByRole('button', { name: 'Edit Silverwing' }).click();
  await page.waitForURL(/\/detail\/silverwing$/);
  await page.getByRole('tab', { name: 'Edit', exact: true }).click();
  await page.locator('#edit-alias').fill('Silver Test');
  await page.locator('#edit-power-index').fill('99');
  await page.getByRole('button', { name: 'Save changes' }).click();
  await page.getByText('Changes saved').waitFor({ timeout: 5000 });
  check('edit saves on detail', true);

  await rail('Dashboard').click();
  await page.waitForURL(/\/dashboard$/);
  const dashText = await body();
  check('edit visible on dashboard (alias)', dashText.includes('Silver Test'));
  const dashRow = page.locator('tbody tr', { hasText: 'Silverwing' }).first();
  check('edit visible on dashboard roster row (power 99)', (await dashRow.innerText()).includes('99'), (await dashRow.innerText()).replace(/\s+/g, ' '));

  await rail('Roster').click();
  await page.waitForURL(/\/roster$/);
  const rosterRow = page.locator('tbody tr', { hasText: 'Silverwing' }).first();
  check('edit visible on roster (power 99)', (await rosterRow.innerText()).includes('99'), (await rosterRow.innerText()).replace(/\s+/g, ' '));

  // 2. Deploy from detail preselects the hero on the missions board and logs a deployment.
  await page.getByRole('button', { name: 'Edit Silverwing' }).click();
  await page.waitForURL(/\/detail\/silverwing$/);
  await page.getByRole('button', { name: 'Deploy', exact: true }).click();
  await page.waitForURL(/\/missions\?hero=silverwing$/);
  check('deploy navigates with preselected hero', true);
  const rowsBefore = await page.locator('tbody tr').count();
  await page.getByRole('button', { name: 'Deploy', exact: true }).click();
  await page.getByText('deployed to', { exact: false }).waitFor({ timeout: 5000 });
  const rowsAfter = await page.locator('tbody tr').count();
  check('deploy logs a mission row', rowsAfter === rowsBefore + 1, `${rowsBefore} -> ${rowsAfter}`);

  // 3. Recruit writes a new hero that the roster and detail screens read.
  await rail('Recruit').click();
  await page.waitForURL(/\/recruit$/);
  await page.locator('#recruit-name').fill('Probe Recruit');
  await page.locator('#recruit-alias').fill('Probe');
  await page.getByRole('button', { name: 'Recruit hero' }).click();
  await page.waitForURL(/\/detail\/probe-recruit$/);
  check('recruit opens new hero record', (await body()).includes('Probe Recruit'));

  // 4. Retire removes the hero and returns to the roster.
  await page.getByRole('button', { name: 'Retire', exact: true }).click();
  await page.getByRole('button', { name: 'Retire hero' }).click();
  await page.waitForURL(/\/roster$/);
  check('retire removes hero from roster', (await body()).includes('12 of 12 heroes'));

  // 5. Threats and missions read shared state.
  await rail('Threats').click();
  await page.waitForURL(/\/threats$/);
  check('threats show response counts', (await body()).includes('responding now'));

  // 6. Settings restore puts example data back.
  await rail('Settings').click();
  await page.waitForURL(/\/settings$/);
  await page.getByRole('button', { name: 'Restore example data' }).click();
  await page.getByRole('button', { name: 'Restore', exact: true }).click();
  await page.getByText('restored', { exact: false }).waitFor({ timeout: 5000 });
  check('settings restore reports', true);

  // 7. Theme toggle reaches the document.
  await page.getByRole('button', { name: 'Switch to dark theme' }).click();
  check('theme toggle sets dark class', await page.evaluate(() => document.documentElement.classList.contains('dark')));

  await context.close();
} catch (e) {
  problems.push('script: ' + e.message);
  console.log('FAIL script: ' + e.message.split('\n')[0]);
} finally {
  await browser.close();
  await srv.close();
}

console.log(problems.length ? `\n${problems.length} problem(s):\n- ${problems.join('\n- ')}` : '\nall flows passed with no runtime errors');

